style.css:
@-moz-document url-prefix("https://pony.town/character") {
/* 1. Главный фон страницы сайта */
body, 
html, 
.site-body {
    background-image: url("https://i.ibb.co/HTBHQdLw/f-Ymjj2-Dg-Gi4qnu-LWUPc-G5rgeyhz-Oece7-Hk2i-HH23okw-Fv6xtb-UKbrxq0-WDo3r6-GYa-L2i2t-Tj7309wi1-Wc4xd-ALg.webp") !important;
    background-size: cover !important;
    background-position: center !important;
    background-attachment: fixed !important;
    background-color: transparent !important;
}

/* 2. Кастомизация главной кнопки «Игровая» */
div[class*="play-button"] > button:first-child,
.btn-success:not([class*="dropdown"]) {
    background-image: url("https://i.ibb.co/rRfwV8TR/504-20260717162134.png") !important;
    background-size: contain !important;
    background-position: center !important;
    background-repeat: no-repeat !important;
    background-color: transparent !important;
    color: transparent !important;
    text-shadow: none !important;
    border: none !important;
    box-shadow: none !important;
    height: 44px !important;
    min-height: 44px !important;
}

/* 3. Кастомизация кнопки списка серверов с прозрачной шестеренкой */
div[class*="play-button"] > button.dropdown-toggle,
button[class*="dropdown-toggle"].btn-success {
    background-image: url("https://i.ibb.co/F4RcGrBt/503-20260717161705.png") !important;
    background-size: contain !important;
    background-position: center !important;
    background-repeat: no-repeat !important;
    background-color: transparent !important;
    color: transparent !important;
    text-shadow: none !important;
    border: none !important;
    box-shadow: none !important;
    width: 42px !important;
    height: 42px !important;
}

/* Убираем стандартный треугольник у этой кнопки */
div[class*="play-button"] .dropdown-toggle::after {
    display: none !important;
}


/* 5. Зеленый фон для списка серверов */
.dropdown-menu,
.dropdown-item,
.dropdown-menu a,
.dropdown-menu button,
.dropdown-menu .ui-text {
    background-color: #5B2E61 !important;
    background: #5B2E61 !important;
    color: #D55897 !important;
}

/* 6. Тотальное окрашивание списка пони и его внутренних блоков */
.ponies-list,
.ponies-list *,
.ponies-list div[style*="max-height"] {
    background-color: #5B2E61 !important;
    background: #5B2E61 !important;
    color: #D55897 !important;
}

/* Мелкий текст тегов в списке пони */
.ponies-list small,
.ponies-list .text-muted,
.dropdown-menu small {
    color: #F8E4F8 !important;
}

/* 7. Поисковая строка внутри списка пони — цвет #99AE9C */
.dropdown-menu input:not([id*="color"]),

div[class*="dropdown-menu"] input:not([id*="color"]),
.ponies-list input {
    background-color: #D55897 !important;
    background: #D55897 !important;
    color: #5B2E61 !important;
}

/* 8. Перекрашивание ползунка (скроллбара) */
.ponies-list,
.ponies-list *,
.dropdown-menu,
.dropdown-menu * {
    scrollbar-color: #D55897 #5B2E61 !important;
}

.ponies-list::-webkit-scrollbar,
.ponies-list *::-webkit-scrollbar,
.dropdown-menu::-webkit-scrollbar,
.dropdown-menu *::-webkit-scrollbar {
    width: 8px !important;
    background-color: #5B2E61 !important;
}

.ponies-list::-webkit-scrollbar-track,
.ponies-list *::-webkit-scrollbar-track,
.dropdown-menu::-webkit-scrollbar-track,
.dropdown-menu *::-webkit-scrollbar-track {
    background-color: #5B2E61 !important;
}

.ponies-list::-webkit-scrollbar-thumb,
.ponies-list *::-webkit-scrollbar-thumb,
.dropdown-menu::-webkit-scrollbar-thumb,
.dropdown-menu *::-webkit-scrollbar-thumb {
    background-color: #D55897 !important;
    border-radius: 4px !important;
}

/* 9. Полная прозрачность фона для боковых кнопок действий в самой игре */
.ui-actions,
[class*="actions"] button,
button[class*="btn-side"],
.sidebar-actions button,
div[style*="position: fixed"] button {
    background-color: transparent !important;
    background: transparent !important;
    box-shadow: none !important;
    border: none !important;
    
    }

/* Прозрачность для остальных фоновых панелей меню */
.site-content, 
.box {
    background: rgba(91, 46, 97, 0.85) !important;
    backdrop-filter: blur(5px) !important;
    border-radius: 12px !important;
}

/* 10. Светло-зеленые иконки и текст игрового интерфейса (кроме чата) */
svg, 
path, 
circle, 
polygon, 
rect,
.ui-icon {
    fill: #D55897 !important;
}

svg[stroke], 
path[stroke] {
    stroke: #D55897 !important;
}

.box:not([id*="chat"]):not([class*="chat"]), 
.ui-panel:not([id*="chat"]):not([class*="chat"]),
.panel:not([id*="chat"]):not([class*="chat"]),
div[style*="position: fixed"]:not([id*="chat"]):not([class*="chat"]),
.ui-text {
    color: #D55897 !important;
}

/* 11. Тотальное перекрашивание серых и белых кнопок/полей (включая внутренние панели опций) */
.btn-default,
.btn-secondary,
.form-control,
select,
.input-group-addon,
button[class*="btn-"],
.character-editor button,
.character-editor select,
.character-editor input:not([type="checkbox"]),
.item-editor button,
.item-editor select,
.item-editor .panel,
.custom-select {
    background-color: #592B7E !important;
    background: #592B7E !important;
    color: #D55897 !important;
    border-color: #7C5094 !important;
    text-shadow: none !important;
    box-shadow: none !important;
}

/* Делаем активные или выбранные вкладки чуть светлее для контраста */
.btn-default.active,
.btn-default:hover,
.character-editor button:hover,
.character-editor button.active,
.item-editor button:hover,
.item-editor button.active {
    background-color: #7C5094 !important;
    background: #7C5094 !important;
    color: #F8E4F8 !important;
}
}
